import type { ErrorFallbackProps } from "./types";

function ErrorFallback({
  availability,
  progress,
  error,
}: ErrorFallbackProps) {
  const isUnavailable = availability === "unavailable";
  const isDownloading =
    availability === "downloadable" || availability === "downloading";
  const isFinishing = isDownloading && progress >= 1;
  const heading = isUnavailable
    ? "This website works best in a browser with built-in AI, such as Google Chrome 138 or newer. You can also find me through the links below."
    : isFinishing
      ? "Your browser is finishing up its on-device AI."
      : isDownloading
        ? "Your browser is downloading its on-device AI."
        : "Your browser is waking up its on-device AI.";
  const description = isUnavailable
    ? "Your portfolio stays in your browser when built-in AI is available. For now, you can still find me through the links in the footer."
    : isFinishing
      ? "The download is complete. Your browser is unpacking the model and getting it ready on your device."
      : isDownloading
        ? "The model is downloading to your device. Your portfolio stays in your browser and nothing is sent to a remote AI service."
        : "Your browser is getting its local model ready. Your portfolio stays on your device and nothing is sent to a remote AI service.";

  return (
    <section className="ai-gate" aria-live="polite">
      <span className="eyebrow">Notice</span>
      <h2>{heading}</h2>
      <p>{description}</p>
      {isDownloading && (
        <div
          className={`progress-track ${isFinishing ? "is-finishing" : ""}`}
          role="progressbar"
          aria-label="On-device AI download progress"
          aria-valuemin={0}
          aria-valuemax={1}
          aria-valuenow={isFinishing ? undefined : progress}
        >
          <span
            style={
              isFinishing
                ? undefined
                : { width: `${Math.max(progress * 100, 4)}%` }
            }
          />
        </div>
      )}
      {error && <p className="error-message">{error}</p>}
    </section>
  );
}

export default ErrorFallback;

@import url("https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700&family=Playfair+Display:ital,wght@0,500;1,500&display=swap");
:root {
  color-scheme: light dark;
  --ink: #171917;
  --muted: #6d7369;
  --paper: #f1f0e9;
  --line: #c8c9bd;
  --acid: #d9ff4f;
  --coral: #ff6b4a;
  --mono: "DM Mono", monospace;
  --sans: "Manrope", sans-serif;
  --serif: "Playfair Display", serif;
}
@media (prefers-color-scheme: dark) {
  :root {
    --ink: #f0f0e8;
    --muted: #a5aa9e;
    --paper: #171917;
    --line: #41453d;
    --acid: #d9ff4f;
    --coral: #ff8064;
  }
}
* {
  box-sizing: border-box;
}
body {
  color: var(--ink);
  background: var(--paper);
  font: 15px/1.6 var(--sans);
}
button,
input {
  font: inherit;
}
button {
  color: inherit;
  cursor: pointer;
}
.site-shell {
  max-width: 1440px;
  min-height: 100svh;
  margin: auto;
  padding: 0 4vw 94px;
}
.site-shell.is-generating {
  cursor: wait;
}
.site-shell.is-generating button,
.site-shell.is-generating input {
  cursor: wait;
}
.site-shell.is-generating .exit-button {
  cursor: pointer;
}
.site-header {
  padding: 32px 0 0;
  border-bottom: 1px solid var(--ink);
}
.header-top,
.header-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.header-top {
  min-height: 54px;
}
.header-bottom {
  gap: 30px;
  padding: 30px 0 18px;
}
.identity {
  flex: 0 0 auto;
  border: 0;
  padding: 0;
  background: transparent;
  color: inherit;
  text-align: left;
}
.identity:hover strong,
.identity:focus-visible strong {
  color: var(--coral);
}
.eyebrow,
.model-status,
.tab-nav span {
  font: 11px var(--mono);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.identity strong {
  display: block;
  font-size: 20px;
  font-weight: 600;
  letter-spacing: -0.05em;
