import type { ErrorFallbackProps } from "./types";

function ErrorFallback({
  availability,
  progress,
  error,
}: ErrorFallbackProps) {
  const isUnavailable = availability === "unavailable";
  const isDownloading = availability === "downloading";
  const heading = isUnavailable
    ? "This website is best experienced in a browser with built-in AI, such as Google Chrome 138 or newer. You can also check out my links below."
    : isDownloading
      ? "Waiting for your browser to finish downloading its AI model."
      : "Waking up your on-device AI.";
  const description = isUnavailable
    ? "Open this site in a supported desktop version of Chrome with Prompt API access, or check out the links in the footer."
    : isDownloading
      ? "The model stays on your device, and the page will refresh when it is ready."
      : "Your browser is getting the on-device AI ready. This should only take a moment.";

  return (
    <section className="ai-gate" aria-live="polite">
      <span className="eyebrow">Notice</span>
      <h2>{heading}</h2>
      <p>{description}</p>
      {isDownloading && (
        <div className="progress-track">
          <span style={{ width: `${Math.max(progress * 100, 4)}%` }} />
        </div>
      )}
      {error && <p className="error-message">{error}</p>}
    </section>
  );
}

export default ErrorFallback;

